import { BlobServiceClient } from "@azure/storage-blob";
import { DefaultAzureCredential } from "@azure/identity";

const accountName = "stabairdnlabeus2001";
const containerName = "raw";
const blobName = "airline-demo-new/airline-demo-new-source-corpus-v1.0.0/03-source-corpus-design/synthetic-source-samples/application-platform-inventory.csv";
try {
  const serviceClient = new BlobServiceClient(`https://${accountName}.blob.core.windows.net`, new DefaultAzureCredential());
  const blobClient = serviceClient.getContainerClient(containerName).getBlobClient(blobName);
  const props = await blobClient.getProperties();
  const download = await blobClient.download(0, 256);
  const chunks = [];
  for await (const chunk of download.readableStreamBody) chunks.push(Buffer.from(chunk));
  console.log(JSON.stringify({
    status: "blob_read_passed",
    accountName,
    containerName,
    blobName,
    contentLength: props.contentLength,
    contentType: props.contentType,
    sample: Buffer.concat(chunks).toString("utf8", 0, 256),
  }, null, 2));
} catch (error) {
  console.log(JSON.stringify({
    status: "blob_read_failed",
    accountName,
    containerName,
    blobName,
    name: error.name,
    code: error.code,
    statusCode: error.statusCode,
    message: error.message,
  }, null, 2));
  process.exitCode = 1;
}
NODE
